"""Test block KpiTile (Charts): A tile with one key number, its change from the last period in words and an arrow, an optional sparkline, and a link to the full report.

Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/charts/KpiTile.md and its markup
(kit/blocks/charts/KpiTile.html, kit/blocks/charts/KpiTile.2.html; source cd6b8b983257), with the vocabulary in
functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.

Steps (e2e):
  Then the {kpi} tile shows {value}
  Then the {kpi} tile change says {text}
  When I open the {kpi} report
  When I show the {kpi} numbers as a table
  Then the {kpi} tile is in the {state} state
States (from the card): Loaded, Good or bad direction, No comparison yet, Loading, Error, Long numbers, Going down.
Checked by the state step: Loaded, No comparison yet, Loading, Going down.
"""
from __future__ import annotations

from functional import Registry
from functional import primitives as p

BLOCK = "KpiTile"
ROUTE = ""
STATES = ["Loaded", "Good or bad direction", "No comparison yet", "Loading", "Error", "Long numbers", "Going down"]
DEFAULT_STATE = "Loaded"
CHECKED_STATES = ["Loaded", "No comparison yet", "Loading", "Going down"]
DEMO = ["kit/blocks/charts/KpiTile.html"]
SELF_TEST = [
    "Then the \"Revenue\" tile shows \"¥420,000\"",
    "Then the Revenue tile change says \"▲ 9 %\"",
    "Then the Revenue tile is in the \"Loaded\" state",
    "When I show the Revenue numbers as a table",
    "When I open the Revenue report",
]

steps = Registry(block=BLOCK)


class KpiTile:
    """The KpiTile block on a page: its controls, found as a person finds them (role and name, label, text)."""

    def __init__(self, page, base_url: str = ""):
        self.page = page
        self.base_url = base_url

    def tile(self, kpi):
        return p.control(self.page, role="region", name=str(kpi), block=BLOCK)

    def change(self, kpi):
        return p.control(self.tile(kpi), css=".badge", block=BLOCK)

    def change_all(self, kpi):
        """Every match, possibly none (for counting)."""
        return self.tile(kpi).locator(".badge")

    def loading(self, kpi):
        return p.control(self.tile(kpi), css="[aria-busy=\"true\"]", block=BLOCK)

    def report(self, kpi):
        return p.control(self.tile(kpi), role="link", name="View report", block=BLOCK)

    def table_toggle(self, kpi):
        return p.control(self.tile(kpi), text="Show as a table", block=BLOCK)

    def expect_state(self, state: str, kpi) -> None:
        """Check one of the card's states: Loaded, No comparison yet, Loading, Going down."""
        b = self
        if state == "Loaded":
            p.expect_visible(b.change(kpi).first)
            p.expect_visible(b.report(kpi))
        elif state == "No comparison yet":
            p.expect_count(b.change_all(kpi), 0)
        elif state == "Loading":
            p.expect_attribute(b.tile(kpi), "aria-busy", "true")
        elif state == "Going down":
            p.expect_text(b.change(kpi), "▼")
        else:
            raise AssertionError(f"KpiTile has no check for the state {state!r}; checked: " + ", ".join(CHECKED_STATES))


@steps.step("Then the {kpi} tile shows {value}", level="e2e")
def then_the_kpi_tile_shows_value(world, kpi, value):
    b = KpiTile(world.page, getattr(world, "base_url", ""))
    p.expect_text(b.tile(kpi), str(value))


@steps.step("Then the {kpi} tile change says {text}", level="e2e")
def then_the_kpi_tile_change_says_text(world, kpi, text):
    b = KpiTile(world.page, getattr(world, "base_url", ""))
    p.expect_text(b.change(kpi), str(text))


@steps.step("When I open the {kpi} report", level="e2e")
def when_i_open_the_kpi_report(world, kpi):
    b = KpiTile(world.page, getattr(world, "base_url", ""))
    p.click(b.report(kpi))


@steps.step("When I show the {kpi} numbers as a table", level="e2e")
def when_i_show_the_kpi_numbers_as_a_table(world, kpi):
    b = KpiTile(world.page, getattr(world, "base_url", ""))
    p.click(b.table_toggle(kpi))


@steps.step("Then the {kpi} tile is in the {state} state", level="e2e")
def then_the_kpi_tile_is_in_the_state_state(world, kpi, state):
    b = KpiTile(world.page, getattr(world, "base_url", ""))
    b.expect_state(state, kpi)
